/*
 * bigload — can the resident load and run a multi-megabyte app?
 *
 * The image carries 3 MiB of pseudo-random bytes (blob.S, generated by
 * gen_blob.py with its FNV-1a hash baked into blob_expected.h). On launch the
 * app re-hashes the blob it was loaded with, shows PASS/FAIL, and writes the
 * result plus heap numbers to /Data/BigLoad/result.txt. Tap to re-check.
 */
#include "hb_raw_surface.h"
#include "hb_sdk.h"
#include "hb_heap.h"
#include "blob_expected.h"

#define OUT_DIR  "/Data/BigLoad"
#define OUT_PATH "/Data/BigLoad/result.txt"

extern const uint8_t bigload_blob[];
extern const uint8_t bigload_blob_end[];

static uint32_t *s_fb;
static int s_w, s_h;

static void text(int x, int y, const char *str, int scale, uint32_t fg)
{
    fg |= 0xff000000u;
    for (; *str; str++, x += 8*scale) {
        const uint8_t *g = hb_font8x8_glyph(*str);
        for (int r = 0; r < 8; r++)
            for (int c = 0; c < 8; c++) {
                if (!(g[r] & (0x80 >> c))) continue;
                for (int sy = 0; sy < scale; sy++)
                    for (int sx = 0; sx < scale; sx++) {
                        int px = x + c*scale + sx, py = y + r*scale + sy;
                        if (px >= 0 && px < s_w && py >= 0 && py < s_h) s_fb[py*s_w + px] = fg;
                    }
            }
    }
}

static char *put_s(char *o, const char *s) { while (*s) *o++ = *s++; *o = 0; return o; }
static char *put_u(char *o, uint32_t u)
{
    char t[12]; int n = 0;
    do { t[n++] = (char)('0' + u % 10); u /= 10; } while (u);
    while (n) *o++ = t[--n];
    *o = 0;
    return o;
}
static char *put_x(char *o, uint32_t u)
{
    static const char hex[] = "0123456789abcdef";
    for (int i = 7; i >= 0; i--) *o++ = hex[(u >> (i * 4)) & 15];
    *o = 0;
    return o;
}

static uint32_t g_size, g_hash, g_us, g_free, g_largest, g_runs;
static int g_pass;
static char g_lines[6][48];

static void check(void)
{
    const uint8_t *p = bigload_blob;
    uint32_t n = (uint32_t)(bigload_blob_end - bigload_blob), h = 0x811c9dc5u;
    uint32_t t0 = hb_time_uptime_us();
    for (uint32_t i = 0; i < n; i++)
        h = (h ^ p[i]) * 0x01000193u;
    g_us = hb_time_uptime_us() - t0;
    g_size = n;
    g_hash = h;
    g_pass = (n == BLOB_SIZE && h == BLOB_FNV);
    g_free = hb_os_heap_free();
    g_largest = hb_os_heap_largest();
    g_runs++;
}

static void report(void)
{
    char *o;
    o = put_s(g_lines[0], g_pass ? "RESULT PASS" : "RESULT FAIL");
    o = put_s(g_lines[1], "BLOB ");      o = put_u(o, g_size); put_s(o, " BYTES");
    o = put_s(g_lines[2], "FNV ");       o = put_x(o, g_hash); o = put_s(o, " WANT "); put_x(o, BLOB_FNV);
    o = put_s(g_lines[3], "HASH TIME "); o = put_u(o, g_us / 1000); put_s(o, " MS");
    o = put_s(g_lines[4], "HEAP FREE "); o = put_u(o, g_free / 1024); put_s(o, "K");
    o = put_s(g_lines[5], "LARGEST ");   o = put_u(o, g_largest / 1024); put_s(o, "K");

    static char buf[400];
    o = buf;
    for (int i = 0; i < 6; i++) { o = put_s(o, g_lines[i]); *o++ = '\n'; }
    o = put_s(o, "RUNS "); o = put_u(o, g_runs); *o++ = '\n';
    hb_fs_mkdir("/Data");
    hb_fs_mkdir(OUT_DIR);
    hb_fs_write(OUT_PATH, buf, (uint32_t)(o - buf));
    hb_trace_log("BIGLOAD ", g_pass, g_hash);

    hb_raw_fill(g_pass ? 0x0e3a1c : 0x4a0e0e);
    text(12, 20, "BIGLOAD", 3, 0xffffff);
    text(12, 70, g_pass ? "PASS" : "FAIL", 6, g_pass ? 0x7ee0a8 : 0xff7070);
    for (int i = 1; i < 6; i++)
        text(12, 150 + i * 26, g_lines[i], 1, 0xdde3ee);
    text(12, s_h - 24, "TAP: CHECK AGAIN", 1, 0x8a93a8);
}

static int g_prev_down;

void hb_raw_init(int w, int h)
{
    s_fb = hb_raw_fb(); s_w = w; s_h = h;
    check();
    report();
}

void hb_raw_frame(const hb_spoint_t *t)
{
    if (!t->down && g_prev_down) { check(); report(); }
    g_prev_down = t->down;
}
